var n=`0599-chicken-tagine-with-preserved-lemon`;var r=`world-0599`;var o=`MA`;var t=`northern-africa`;var a=4;var s=139;var g={en:`Chicken Tagine with Preserved Lemon`,ua:`Курячий тажин із солоним лимоном`};var l={en:`A traditional dish from Morocco, centered on chicken thigh, preserved lemons, garlic, yellow onion. A measured home-kitchen version organized by cooking step. Preserved lemons and green olives provide the characteristic bright-salty flavor of a Moroccan tagine.`,ua:`Традиційна страва кухні країни Марокко. Основні складники: куряче стегно, солоні лимони, часник, жовта цибуля. Домашній варіант із кількостями продуктів за етапами приготування. Консервовані лимони й зелені оливки надають марокканському тажину характерного кисло-солоного смаку.`};var c=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 55 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 55 хвилин.`,t:[`marinating`],m:55,i:[[`chicken-thigh`,880,`g`],[`preserved-lemons`,110,`g`],[`extra-virgin-olive-oil`,50,`ml`],[`garlic`,5,`clove`],[`ground-turmeric`,4,`g`],[`ground-ginger`,7,`g`]]},{en:`Slowly braise the marinated chicken with onions, preserved lemon and olives in a covered tagine or heavy casserole, until the meat is tender and fully cooked.`,ua:`Повільно тушкуйте мариновану курятину з цибулею, солоним лимоном та оливками під кришкою тажина або важкої каструлі до ніжності й повної готовності.`,t:[`braising`],m:80,i:[[`yellow-onion`,260,`g`],[`water`,450,`ml`],[`saffron-threads`,.3,`g`],[`green-olives`,170,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`cilantro`,25,`g`]]}];var d={slug:n,id:r,country:`MA`,region:t,servings:4,minutes:139,title:g,text:l,steps:c};export{o as country,d as default,r as id,s as minutes,t as region,a as servings,n as slug,c as steps,l as text,g as title};